use std::collections::BinaryHeap;use std::cmp::Reverse;struct MedianFinder{lo:BinaryHeap<i32>,hi:BinaryHeap<Reverse<i32>>}impl MedianFinder{fn new()->Self{Self{lo:BinaryHeap::new(),hi:BinaryHeap::new()}}fn add_num(&mut self,x:i32){if self.lo.peek().map(|&v|x<=v).unwrap_or(true){self.lo.push(x)}else{self.hi.push(Reverse(x))}if self.lo.len()>self.hi.len()+1{self.hi.push(Reverse(self.lo.pop().unwrap()))}else if self.hi.len()>self.lo.len(){self.lo.push(self.hi.pop().unwrap().0)}}fn find_median(&self)->f64{if self.lo.len()==self.hi.len(){(*self.lo.peek().unwrap()as f64+self.hi.peek().unwrap().0 as f64)/2.0}else{*self.lo.peek().unwrap()as f64}}}
